[
  {
    "alert_id": "ALERT_001",
    "title": "Rising creatinine and declining eGFR on TDF",
    "message": "Guidelines require serum creatinine and eGFR monitoring for patients on TDF, and list chronic kidney disease and acute kidney injury as TDF toxicities. This patient's creatinine has risen steadily from 0.9 (2020) to 1.4 mg/dL (2026), with eGFR now 52 mL/min/1.73m², meeting Grade 2 renal toxicity. TDF is a known cause of renal toxicity and Fanconi syndrome. Evidence against drug attribution: no back pain, no change in urine volume, no oedema, and no costovertebral angle tenderness. However, the progressive decline over 3 years on TDF strongly suggests drug-related nephrotoxicity. Occasional ibuprofen use may compound renal risk. Non-drug causes should also be excluded.",
    "issue_type": "toxicity",
    "severity": "high",
    "recommended_action": "Evaluate for TDF nephrotoxicity vs other causes. Consider switching TDF to TAF or AZT-based regimen. Monitor renal function closely and address concurrent ibuprofen use.",
    "citations": [
      {"page_number": 270, "chunk_id": "hiv_guidelines_art.extraction__hiv_guidelines_art.extraction__p37_c1"},
      {"page_number": 260, "chunk_id": "hiv_guidelines_art.extraction__hiv_guidelines_art.extraction__p27_c2"},
      {"page_number": 265, "chunk_id": "hiv_guidelines_art.extraction__hiv_guidelines_art.extraction__p32_c1"}
    ]
  },
  {
    "alert_id": "ALERT_002",
    "title": "No clinician assessment or plan documented",
    "message": "Guidelines require monitoring for signs and symptoms of adverse drug reactions and appropriate management when deranged labs are detected. Today's encounter has no written assessment or plan despite significant renal function decline (eGFR 52, creatinine 1.4) and proteinuria (1+). The clinician has not addressed the abnormal renal findings, has not ordered repeat renal function tests, and has not documented any management decision regarding TDF continuation or substitution. This represents a guideline deviation and a plan gap.",
    "issue_type": "plan_review",
    "severity": "high",
    "recommended_action": "Document assessment of renal function decline and proteinuria. Order repeat renal function tests and urinalysis. Decide on TDF continuation vs substitution and document rationale.",
    "citations": [
      {"page_number": 270, "chunk_id": "hiv_guidelines_art.extraction__hiv_guidelines_art.extraction__p37_c1"},
      {"page_number": 260, "chunk_id": "hiv_guidelines_art.extraction__hiv_guidelines_art.extraction__p27_c2"}
    ]
  },
  {
    "alert_id": "ALERT_003",
    "title": "Proteinuria with declining eGFR warrants further workup",
    "message": "The patient has protein 1+ on urinalysis alongside an eGFR of 52 mL/min/1.73m² and a steadily rising creatinine. Guidelines list chronic kidney disease as a TDF toxicity and recommend renal function tests when deranged. Proteinuria in the context of TDF use may indicate early tubular damage (Fanconi syndrome spectrum). The trace glucose on urinalysis further supports possible proximal tubular dysfunction. Alternative causes include underlying renal disease independent of TDF. A urine protein-to-creatinine ratio and renal ultrasound would help differentiate.",
    "issue_type": "monitoring_gap",
    "severity": "moderate",
    "recommended_action": "Order urine protein-to-creatinine ratio, renal ultrasound, and electrolytes including phosphate and urate to evaluate for TDF-induced tubular dysfunction vs other renal pathology.",
    "citations": [
      {"page_number": 270, "chunk_id": "hiv_guidelines_art.extraction__hiv_guidelines_art.extraction__p37_c1"},
      {"page_number": 260, "chunk_id": "hiv_guidelines_art.extraction__hiv_guidelines_art.extraction__p27_c2"}
    ]
  },
  {
    "alert_id": "ALERT_004",
    "title": "Fatigue may signal TDF or DTG-related toxicity",
    "message": "Guidelines list exhaustion or extreme fatigue as a presenting sign of TDF toxicity (lactic acidosis or severe hepatomegaly with steatosis) and also as a sign associated with AZT, though the patient is not on AZT. The patient reports mild fatigue over 2 months. Evidence for drug attribution: fatigue is a listed TDF toxicity sign. Evidence against: the patient attributes it to work schedule, fatigue is mild, and no other symptoms such as abdominal pain, decreased appetite, or muscle cramps are reported. LFTs should be checked to evaluate for hepatic involvement.",
    "issue_type": "toxicity",
    "severity": "moderate",
    "recommended_action": "Perform LFTs and RFTs to evaluate for TDF-related toxicity. If deranged, manage per guideline toxicity protocol. Consider alternative causes of fatigue.",
    "citations": [
      {"page_number": 270, "chunk_id": "hiv_guidelines_art.extraction__hiv_guidelines_art.extraction__p37_c1"},
      {"page_number": 270, "chunk_id": "hiv_guidelines_art.extraction__hiv_guidelines_art.extraction__p37_c2"}
    ]
  }
]
